184→export async function searchCheckpoints(
185→  turbopufferApiKey: string,
186→  openaiApiKey: string,
187→  githubId: number,
188→  query: string,
189→  filters?: { branch?: string },
190→  limit: number = 50,
191→): Promise<TurbopufferSearchResult[]> {
192→  const namespace = `checkpoints-gh-${githubId}`;
193→
194→  const headers = {
195→    Authorization: `Bearer ${turbopufferApiKey}`,
196→    "Content-Type": "application/json",
197→  };
198→
199→  const branchFilters = filters?.branch
200→    ? { branch: [["Eq", filters.branch]] }
201→    : undefined;
202→
203→  // Fire vector + BM25 queries in parallel, gracefully degrade if either fails
204→  const [vectorResult, bm25Result] = await Promise.all([
205→    // Vector cosine similarity (v1 API)
206→    (async (): Promise<{ rows: SearchRow[]; error?: string }> => {
207→      try {
208→        const vector = await embedQuery(openaiApiKey, query);
209→        const url = `https://api.turbopuffer.com/v1/vectors/${encodeURIComponent(namespace)}/query`;
210→        const body: Record<string, unknown> = {
211→          vector,
212→          top_k: limit,
213→          distance_metric: "cosine_distance",
214→          include_attributes: ["checkpoint_id"],
215→        };
216→        if (branchFilters) body.filters = branchFilters;
217→
218→        const resp = await fetch(url, {
219→          method: "POST",
220→          headers,
221→          body: JSON.stringify(body),
222→        });
223→        if (!resp.ok) {
224→          const text = await resp.text().catch(() => "");
225→          return { rows: [], error: `vector query failed (${resp.status}): ${text}` };
226→        }
227→        const rows = (await resp.json()) as TurbopufferV1Row[];
228→        return { rows: rows.map((r) => ({ checkpoint_id: r.attributes?.checkpoint_id, dist: r.dist })) };
229→      } catch (err) {
230→        return { rows: [], error: `vector query error: ${err instanceof Error ? err.message : String(err)}` };
231→      }
232→    })(),
233→
234→    // BM25 full-text search (v2 API)
235→    (async (): Promise<{ rows: SearchRow[]; error?: string }> => {
236→      try {
237→        const url = `https://api.turbopuffer.com/v2/namespaces/${encodeURIComponent(namespace)}/query`;
238→        const body: Record<string, unknown> = {
239→          rank_by: ["text", "BM25", query],
240→          top_k: limit,
241→          include_attributes: ["checkpoint_id"],
242→        };
243→        if (branchFilters) body.filters = branchFilters;
244→
245→        const resp = await fetch(url, {
246→          method: "POST",
247→          headers,
248→          body: JSON.stringify(body),
249→        });
250→        if (!resp.ok) {
251→          const text = await resp.text().catch(() => "");
252→          return { rows: [], error: `BM25 query failed (${resp.status}): ${text}` };
253→        }
254→        const data = (await resp.json()) as TurbopufferV2Response;
255→        return { rows: data.rows.map((r) => ({ checkpoint_id: r.checkpoint_id, dist: r.$dist })) };
256→      } catch (err) {
257→        return { rows: [], error: `BM25 query error: ${err instanceof Error ? err.message : String(err)}` };
258→      }
259→    })(),
260→  ]);
261→
262→  const vectorResults = vectorResult.rows;
263→  const bm25Results = bm25Result.rows;
264→
265→  if (vectorResult.error) console.warn(`[search] ${vectorResult.error}`);
266→  if (bm25Result.error) console.warn(`[search] ${bm25Result.error}`);
267→
268→  // If both failed, return empty so client falls back to local filtering
269→  if (vectorResults.length === 0 && bm25Results.length === 0) {
270→    console.warn(`[search] both sources returned no results`);
271→    return [];
272→  }
273→
274→  console.log(`[search] query="${query}" namespace=${namespace}`);
275→  console.log(`[search] vector results: ${vectorResults.length}, bm25 results: ${bm25Results.length}`);
276→
277→  // Log top results from each source with their raw scores
278→  const topN = 5;
279→  if (vectorResults.length > 0) {
280→    console.log(`[search] top ${topN} vector (cosine dist):`,
281→      vectorResults.slice(0, topN).map((r, i) => ({
282→        rank: i + 1,
283→        checkpoint_id: r.checkpoint_id?.slice(0, 8),
284→        dist: r.dist?.toFixed(4),
285→      })),
286→    );
287→  }
288→  if (bm25Results.length > 0) {
289→    console.log(`[search] top ${topN} bm25:`,
290→      bm25Results.slice(0, topN).map((r, i) => ({
291→        rank: i + 1,
292→        checkpoint_id: r.checkpoint_id?.slice(0, 8),
293→        dist: r.dist?.toFixed(4),
294→      })),
295→    );
296→  }
297→
298→  const merged = mergeRRF(vectorResults, bm25Results, limit);
299→
300→  // Log final merged results
301→  console.log(`[search] top ${topN} RRF merged:`,
302→    merged.slice(0, topN).map((r) => ({
303→      checkpoint_id: r.checkpoint_id.slice(0, 8),
304→      rrf: r.rrf.toFixed(6),
305→      vectorRank: r.vectorRank,
306→      bm25Rank: r.bm25Rank,
307→      source: r.vectorRank && r.bm25Rank ? "both" : r.vectorRank ? "vector-only" : "bm25-only",
308→    })),
309→  );
310→
311→  return merged.map((r) => ({ checkpoint_id: r.checkpoint_id }));
312→}
