 50→
 51→export function CheckpointsPage(props: CheckpointsPageProps) {
 52→  const { org, repo, branch } = props;
 53→  const navigate = useNavigate();
 54→  const queryClient = useQueryClient();
 55→  const [searchQuery, setSearchQuery] = useState("");
 56→  const { data: statusData, error: statusError } = useCheckpointStatusQuery(org, repo);
 57→  const { data, isLoading, error } = useCheckpointsQuery(org, repo, branch);
 58→  const { data: branchesData } = useBranchesQuery(org, repo);
 59→  const repoOptions = useRepoBreadcrumbOptions(org);
 60→
 61→  const handleBranchChange = (newBranch: string | null) => {
 62→    if (!newBranch) return;
 63→    navigate({
 64→      to: "/gh/$org/$repo/checkpoints/$branch",
 65→      params: { org, repo, branch: newBranch },
 66→    });
 67→  };
 68→
 69→  const branches = branchesData?.branches ?? [];
 70→  const defaultBranch = branchesData?.default_branch ?? "main";
 71→
 72→  // Sort branches with default branch first, then create options for Combobox
 73→  const sortedBranches = [...branches].sort((a, b) => {
 74→    if (a === defaultBranch) return -1;
 75→    if (b === defaultBranch) return 1;
 76→    return a.localeCompare(b);
 77→  });
 78→
 79→  const branchOptions: ComboboxOption[] = sortedBranches.map((b) => ({
 80→    id: b,
 81→    label: b,
 82→  }));
 83→  // Debounce search query for API calls
 84→  const [debouncedQuery, setDebouncedQuery] = useState("");
 85→  useEffect(() => {
 86→    const timer = setTimeout(() => setDebouncedQuery(searchQuery.trim()), 300);
 87→    return () => clearTimeout(timer);
 88→  }, [searchQuery]);
 89→
 90→  const { data: searchData, isFetching: isSearching } = useSearchCheckpointsQuery(
 91→    org, repo, debouncedQuery, branch,
 92→  );
 93→
 94→  const isSearchActive = debouncedQuery.length > 0;
 95→  const allCheckpoints = data?.checkpoints ?? [];
 96→  const checkpoints = isSearchActive
 97→    ? (searchData?.checkpoints ?? [])
 98→    : allCheckpoints;
 99→
100→  // =============================================================================
101→  // LOCAL DEV ONLY: Fetch from GitHub button
102→  // In local development, the D1 database isn't populated with checkpoint data.
103→  // This button fetches directly from GitHub to allow testing the UI.
104→  // import.meta.env.DEV is false in production builds, so this code is tree-shaken.
105→  // =============================================================================
106→  const isDev = import.meta.env.DEV;
107→  const [isFetchingFromGitHub, setIsFetchingFromGitHub] = useState(false);
108→
109→  const handleFetchFromGitHub = async () => {
110→    setIsFetchingFromGitHub(true);
111→    try {
112→      const response = await fetchCheckpoints(org, repo, branch, {
113→        source: "github",
114→      });
115→      queryClient.setQueryData(
116→        ["github", "checkpoints", org, repo, branch],
117→        response,
118→      );
119→    } catch (err) {
120→      console.error("Failed to fetch from GitHub:", err);
121→    } finally {
122→      setIsFetchingFromGitHub(false);
123→    }
124→  };
125→  // =============================================================================
126→
127→  // Use whichever error arrives first (status is faster, catches 404s early)
128→  const anyError = statusError || error;
129→  const isRepoNotFound = anyError?.message.includes("Repository not found");
130→
131→  // Repo-level 404 — render the standard not-found page
132→  if (isRepoNotFound) {
133→    return (
134→      <Page noPadding>
135→        <div className="flex min-h-[calc(100dvh-var(--global-header-height))]">
136→          <NotFoundContent />
137→        </div>
138→      </Page>
139→    );
140→  }
141→
142→  if (isAuthError(anyError)) {
143→    return (
144→      <Page pageTitle={`${org}/${repo}`} breadcrumbs={(statusData || data) ? getCheckpointBreadcrumbs({ org, repo, branch, repoOptions }) : undefined}>
145→        <ReauthenticateState />
146→      </Page>
147→    );
148→  }
149→
150→  const isBranchNotFound = error instanceof ApiError && error.status === 404;
151→  const genericError = isBranchNotFound ? statusError : anyError;
152→  if (genericError && !isBranchNotFound) {
153→    return (
154→      <Page pageTitle={`${org}/${repo}`} breadcrumbs={(statusData || data) ? getCheckpointBreadcrumbs({ org, repo, branch, repoOptions }) : undefined}>
155→        <div className="border border-default rounded bg-raised p-8">
156→          <div className="text-center">
157→            <p className="text-red-500">
158→              Failed to load checkpoints: {genericError.message}
159→            </p>
160→          </div>
161→        </div>
162→      </Page>
163→    );
164→  }
165→
166→  const hasCheckpoints = data && data.checkpoints.length > 0;
167→  const noCheckpoints = data && data.checkpoints.length === 0;
168→  // Use the fast status query to decide UI before checkpoints finish loading
169→  const repoHasCheckpoints = statusData && statusData.checkpoint_count > 0;
170→  // Show toolbar when we know there are checkpoints (or data already loaded with them)
171→  const showToolbar = hasCheckpoints || repoHasCheckpoints || data?.session_branch_exists === true;
172→
173→  // Empty state conditions — use full data when available, fall back to status data (with error guard)
174→  const showNoAccess =
175→    (noCheckpoints && data.app_has_access === false) ||
176→    (!data && !anyError && statusData?.checkpoint_count === 0 && statusData?.app_has_access === false);
177→
178→  // CLI install: app has access but no session branch yet (null means not synced)
179→  const showCliInstall =
180→    (noCheckpoints && data.app_has_access === true && !data.session_branch_exists) ||
181→    (!data && !anyError && statusData?.checkpoint_count === 0 && statusData?.app_has_access === true && !statusData.session_branch_exists);
182→
183→  const showNoBranchCheckpoints =
184→    noCheckpoints && data.app_has_access === true && data.session_branch_exists === true;
185→
186→  return (
187→    <Page pageTitle={`${org}/${repo}`} breadcrumbs={(statusData || data) ? getCheckpointBreadcrumbs({ org, repo, branch, repoOptions }) : undefined}>
188→      {/* Branch selector and search */}
189→      {showToolbar && <div className="pt-4 pb-4 flex items-center gap-2">
190→        <Combobox
191→          options={branchOptions}
192→          size="large"
193→          value={[branch]}
194→          onChange={(selected) => handleBranchChange(selected[0] ?? null)}
195→        >
196→          <ComboboxTrigger className="max-w-52 shrink-0 justify-start">
197→            <span className="flex items-center gap-1.5 w-full">
198→              <BranchIcon size={18} className="shrink-0" />
199→              <span className="truncate">{branch}</span>
200→              <ChevronDownIcon size={18} className="shrink-0 ml-auto" />
201→            </span>
202→          </ComboboxTrigger>
203→          <ComboboxContent>
204→            <ComboboxInput placeholder="Search branches..." />
205→            <ComboboxList emptyMessage="No branches found.">
206→              <BranchOptions defaultBranch={defaultBranch} />
207→            </ComboboxList>
208→          </ComboboxContent>
209→        </Combobox>
210→
211→        <div className="min-w-45 md:min-w-65 lg:min-w-[320px] ml-auto">
212→          <Input
213→            type="text"
214→            placeholder="Search checkpoints..."
215→            value={searchQuery}
216→            onChange={(e) => setSearchQuery(e.target.value)}
217→            icon={<SearchIcon />}
218→          />
219→        </div>
220→      </div>}
221→
222→      {/* Loading state - only show skeleton once status confirms checkpoints exist */}
223→      {isLoading && repoHasCheckpoints && <CheckpointsSkeleton />}
224→
225→      {isBranchNotFound && (
226→        <ErrorState selectedBranch={branch} hasBranches={branches.length > 0} />
227→      )}
228→
229→      {checkpoints.length > 0 && (hasCheckpoints || isSearchActive) && (
230→        <div className="relative">
231→          {isSearchActive && isSearching && (
232→            <div className="absolute top-0 left-0 right-0 h-0.5 bg-orange-500/30 overflow-hidden rounded-t">
233→              <div className="h-full w-1/3 bg-orange-500 animate-[shimmer_1s_ease-in-out_infinite]" />
234→            </div>
235→          )}
236→          <CheckpointsList
237→            checkpoints={checkpoints}
238→            navigate={navigate}
239→            isDev={isDev}
240→            isFetchingFromGitHub={isFetchingFromGitHub}
241→            handleFetchFromGitHub={handleFetchFromGitHub}
242→            org={org}
243→            repo={repo}
244→            branch={branch}
245→          />
246→        </div>
247→      )}
248→
249→      {/* Empty search results */}
250→      {isSearchActive &&
251→        !isSearching &&
252→        checkpoints.length === 0 &&
253→        searchData && (
254→          <div className="border border-default rounded bg-raised p-8">
255→            <div className="text-center text-muted">
256→              <p className="text-lg font-medium">No matching checkpoints</p>
257→              <p className="mt-2 text-sm max-w-md mx-auto">
258→                No checkpoints match &ldquo;{searchQuery}&rdquo;. Try a different search
259→                term.
260→              </p>
261→            </div>
262→          </div>
263→        )}
264→
265→      {/* Empty state: App doesn't have access */}
266→      {showNoAccess && (
267→        <div className="flex items-center justify-center min-h-[calc(100vh-var(--global-header-height)-120px)]">
268→          <div className="text-center text-muted py-12 px-8">
269→            <p className="text-xl font-semibold text-default">
270→              Grant access to this repository
271→            </p>
272→            <p className="mt-3 text-sm max-w-md mx-auto">
273→              The GitHub App needs access to this repository to track your
274→              Claude Code sessions.
275→            </p>
276→            <p className="mt-6 text-sm">
277→              <a
278→                href={getGitHubInstallationUrl()}
279→                className="text-orange-500 hover:underline"
280→              >
281→                Configure GitHub App access
282→              </a>
283→            </p>
284→            {isDev && (
285→              <div className="mt-4">
286→                <Button
287→                  variant="outline"
288→                  onClick={handleFetchFromGitHub}
289→                  disabled={isFetchingFromGitHub}
290→                >
291→                  {isFetchingFromGitHub ? "Fetching..." : "Fetch from GitHub"}
292→                </Button>
293→              </div>
294→            )}
295→          </div>
296→        </div>
297→      )}
298→
299→      {/* Empty state: App has access but no session branch (CLI not used yet) */}
300→      {showCliInstall && (
301→        <div className="flex items-center justify-center min-h-[calc(100vh-var(--global-header-height)-120px)]">
302→          <div>
303→            <CliInstallationSteps />
304→            {isDev && (
305→              <div className="flex justify-center pb-8">
306→                <Button
307→                  variant="outline"
308→                  onClick={handleFetchFromGitHub}
309→                  disabled={isFetchingFromGitHub}
310→                >
311→                  {isFetchingFromGitHub ? "Fetching..." : "Fetch from GitHub"}
312→                </Button>
313→              </div>
314→            )}
315→          </div>
316→        </div>
317→      )}
318→
319→      {/* Empty state: App has access and session branch exists, but no checkpoints on this branch */}
320→      {showNoBranchCheckpoints && (
321→        <div className="border border-default rounded bg-raised p-8">
322→          <div className="text-center text-muted">
323→            <p className="text-lg font-medium">
324→              No checkpoints on this branch
325→            </p>
326→            <p className="mt-2 text-sm max-w-md mx-auto">
327→              This repository has Claude Code sessions, but none of them are
328→              linked to commits on the{" "}
329→              <code className="font-mono bg-muted px-1 rounded">
330→                {branch}
331→              </code>{" "}
332→              branch.
333→            </p>
334→            {isDev && (
335→              <div className="mt-4">
336→                <Button
337→                  variant="outline"
338→                  onClick={handleFetchFromGitHub}
339→                  disabled={isFetchingFromGitHub}
340→                >
341→                  {isFetchingFromGitHub ? "Fetching..." : "Fetch from GitHub"}
342→                </Button>
343→              </div>
344→            )}
345→          </div>
346→        </div>
347→      )}
348→
349→    </Page>
350→  );
