 61→
 62→  const handleBranchChange = (newBranch: string | null) => {
 63→    if (!newBranch) return;
 64→    navigate({
 65→      to: "/gh/$org/$repo/checkpoints/$branch",
 66→      params: { org, repo, branch: newBranch },
 67→    });
 68→  };
 69→
 70→  const branches = branchesData?.branches ?? [];
 71→  const defaultBranch = branchesData?.default_branch ?? "main";
 72→
 73→  // Sort branches with default branch first, then create options for Combobox
 74→  const sortedBranches = [...branches].sort((a, b) => {
 75→    if (a === defaultBranch) return -1;
 76→    if (b === defaultBranch) return 1;
 77→    return a.localeCompare(b);
 78→  });
 79→
 80→  const branchOptions: ComboboxOption[] = sortedBranches.map((b) => ({
 81→    id: b,
 82→    label: b,
 83→  }));
 84→  // Debounce search query for API calls
 85→  const [debouncedQuery, setDebouncedQuery] = useState("");
 86→  useEffect(() => {
 87→    const timer = setTimeout(() => setDebouncedQuery(searchQuery.trim()), 300);
 88→    return () => clearTimeout(timer);
 89→  }, [searchQuery]);
 90→
 91→  const { data: searchData, isFetching: isSearching } = useSearchCheckpointsQuery(
 92→    org, repo, debouncedQuery, branch,
 93→  );
 94→
 95→  const isSearchActive = debouncedQuery.length > 0;
 96→  const allCheckpoints = data?.checkpoints ?? [];
 97→  const checkpoints = isSearchActive
 98→    ? (searchData?.checkpoints ?? [])
 99→    : allCheckpoints;
100→
101→  // =============================================================================
102→  // LOCAL DEV ONLY: Fetch from GitHub button
103→  // In local development, the D1 database isn't populated with checkpoint data.
104→  // This button fetches directly from GitHub to allow testing the UI.
105→  // import.meta.env.DEV is false in production builds, so this code is tree-shaken.
106→  // =============================================================================
107→  const isDev = import.meta.env.DEV;
108→  const [isFetchingFromGitHub, setIsFetchingFromGitHub] = useState(false);
109→
110→  const handleFetchFromGitHub = async () => {
111→    setIsFetchingFromGitHub(true);
112→    try {
113→      const response = await fetchCheckpoints(org, repo, branch, {
114→        source: "github",
115→      });
116→      queryClient.setQueryData(
117→        ["github", "checkpoints", org, repo, branch],
118→        response,
119→      );
120→    } catch (err) {
121→      console.error("Failed to fetch from GitHub:", err);
122→    } finally {
123→      setIsFetchingFromGitHub(false);
124→    }
125→  };
126→  // =============================================================================
127→
128→  // Use whichever error arrives first (status is faster, catches 404s early)
129→  const anyError = statusError || error;
130→  const isRepoNotFound = anyError?.message.includes("Repository not found");
131→
132→  // Repo-level 404 — render the standard not-found page
133→  if (isRepoNotFound) {
134→    return (
135→      <Page noPadding>
136→        <div className="flex min-h-[calc(100dvh-var(--global-header-height))]">
137→          <NotFoundContent />
138→        </div>
139→      </Page>
140→    );
141→  }
142→
143→  if (isAuthError(anyError)) {
144→    return (
145→      <Page pageTitle={`${org}/${repo}`} breadcrumbs={(statusData || data) ? getCheckpointBreadcrumbs({ org, repo, branch, repoOptions }) : undefined}>
146→        <ReauthenticateState />
147→      </Page>
148→    );
149→  }
150→
151→  const isBranchNotFound = error instanceof ApiError && error.status === 404;
152→  const genericError = isBranchNotFound ? statusError : anyError;
153→  if (genericError && !isBranchNotFound) {
154→    return (
155→      <Page pageTitle={`${org}/${repo}`} breadcrumbs={(statusData || data) ? getCheckpointBreadcrumbs({ org, repo, branch, repoOptions }) : undefined}>
156→        <div className="border border-default rounded bg-raised p-8">
157→          <div className="text-center">
158→            <p className="text-red-500">
159→              Failed to load checkpoints: {genericError.message}
160→            </p>
161→          </div>
162→        </div>
163→      </Page>
164→    );
165→  }
166→
167→  const hasCheckpoints = data && data.checkpoints.length > 0;
168→  const noCheckpoints = data && data.checkpoints.length === 0;
169→  // Use the fast status query to decide UI before checkpoints finish loading
170→  const repoHasCheckpoints = statusData && statusData.checkpoint_count > 0;
171→  // Show toolbar when we know there are checkpoints (or data already loaded with them)
172→  const showToolbar = hasCheckpoints || repoHasCheckpoints || data?.session_branch_exists === true;
173→
174→  // Empty state conditions — use full data when available, fall back to status data (with error guard)
175→  const showNoAccess =
176→    (noCheckpoints && data.app_has_access === false) ||
177→    (!data && !anyError && statusData?.checkpoint_count === 0 && statusData?.app_has_access === false);
178→
179→  // CLI install: app has access but no session branch yet (null means not synced)
180→  const showCliInstall =
181→    (noCheckpoints && data.app_has_access === true && !data.session_branch_exists) ||
182→    (!data && !anyError && statusData?.checkpoint_count === 0 && statusData?.app_has_access === true && !statusData.session_branch_exists);
183→
184→  const showNoBranchCheckpoints =
185→    noCheckpoints && data.app_has_access === true && data.session_branch_exists === true;
186→
187→  return (
188→    <Page pageTitle={`${org}/${repo}`} breadcrumbs={(statusData || data) ? getCheckpointBreadcrumbs({ org, repo, branch, repoOptions }) : undefined}>
189→      {/* Branch selector and search */}
190→      {showToolbar && <div className="pt-4 pb-4 flex items-center gap-2">
191→        <Combobox
192→          options={branchOptions}
193→          size="large"
194→          value={[branch]}
195→          onChange={(selected) => handleBranchChange(selected[0] ?? null)}
196→        >
197→          <ComboboxTrigger className="max-w-52 shrink-0 justify-start">
198→            <span className="flex items-center gap-1.5 w-full">
199→              <BranchIcon size={18} className="shrink-0" />
200→              <span className="truncate">{branch}</span>
201→              <ChevronDownIcon size={18} className="shrink-0 ml-auto" />
202→            </span>
203→          </ComboboxTrigger>
204→          <ComboboxContent>
205→            <ComboboxInput placeholder="Search branches..." />
206→            <ComboboxList emptyMessage="No branches found.">
207→              <BranchOptions defaultBranch={defaultBranch} />
208→            </ComboboxList>
209→          </ComboboxContent>
210→        </Combobox>
211→
212→        <div className="min-w-45 md:min-w-65 lg:min-w-[320px] ml-auto">
213→          <Input
214→            type="text"
215→            placeholder="Search checkpoints..."
216→            value={searchQuery}
217→            onChange={(e) => setSearchQuery(e.target.value)}
218→            icon={<SearchIcon />}
219→          />
220→        </div>
221→      </div>}
222→
223→      {/* Loading state - only show skeleton once status confirms checkpoints exist */}
224→      {isLoading && repoHasCheckpoints && <CheckpointsSkeleton />}
225→
226→      {isBranchNotFound && (
227→        <ErrorState selectedBranch={branch} hasBranches={branches.length > 0} />
228→      )}
229→
230→      {checkpoints.length > 0 && (hasCheckpoints || isSearchActive) && (
231→        <div className="relative">
232→          {isSearchActive && isSearching && (
233→            <div className="absolute top-0 left-0 right-0 h-0.5 bg-orange-500/30 overflow-hidden rounded-t">
234→              <div className="h-full w-1/3 bg-orange-500 animate-[shimmer_1s_ease-in-out_infinite]" />
235→            </div>
236→          )}
237→          <CheckpointsList
238→            checkpoints={checkpoints}
239→            navigate={navigate}
240→            isDev={isDev}
241→            isFetchingFromGitHub={isFetchingFromGitHub}
242→            handleFetchFromGitHub={handleFetchFromGitHub}
243→            org={org}
244→            repo={repo}
245→            branch={branch}
246→            searchQuery={isSearchActive ? debouncedQuery : ""}
247→            searchMeta={isSearchActive ? searchData?.searchMeta : undefined}
248→          />
249→        </div>
250→      )}
251→
252→      {/* Empty search results */}
253→      {isSearchActive &&
254→        !isSearching &&
255→        checkpoints.length === 0 &&
256→        searchData && (
257→          <div className="border border-default rounded bg-raised p-8">
258→            <div className="text-center text-muted">
259→              <p className="text-lg font-medium">No matching checkpoints</p>
260→              <p className="mt-2 text-sm max-w-md mx-auto">
261→                No checkpoints match &ldquo;{searchQuery}&rdquo;. Try a different search
262→                term.
263→              </p>
264→            </div>
265→          </div>
266→        )}
267→
268→      {/* Empty state: App doesn't have access */}
269→      {showNoAccess && (
270→        <div className="flex items-center justify-center min-h-[calc(100vh-var(--global-header-height)-120px)]">
271→          <div className="text-center text-muted py-12 px-8">
272→            <p className="text-xl font-semibold text-default">
273→              Grant access to this repository
274→            </p>
275→            <p className="mt-3 text-sm max-w-md mx-auto">
276→              The GitHub App needs access to this repository to track your
277→              Claude Code sessions.
278→            </p>
279→            <p className="mt-6 text-sm">
280→              <a
281→                href={getGitHubInstallationUrl()}
282→                className="text-orange-500 hover:underline"
283→              >
284→                Configure GitHub App access
285→              </a>
286→            </p>
287→            {isDev && (
288→              <div className="mt-4">
289→                <Button
290→                  variant="outline"
291→                  onClick={handleFetchFromGitHub}
292→                  disabled={isFetchingFromGitHub}
293→                >
294→                  {isFetchingFromGitHub ? "Fetching..." : "Fetch from GitHub"}
295→                </Button>
296→              </div>
297→            )}
298→          </div>
299→        </div>
300→      )}
301→
302→      {/* Empty state: App has access but no session branch (CLI not used yet) */}
303→      {showCliInstall && (
304→        <div className="flex items-center justify-center min-h-[calc(100vh-var(--global-header-height)-120px)]">
305→          <div>
306→            <CliInstallationSteps />
307→            {isDev && (
308→              <div className="flex justify-center pb-8">
309→                <Button
310→                  variant="outline"
311→                  onClick={handleFetchFromGitHub}
312→                  disabled={isFetchingFromGitHub}
313→                >
314→                  {isFetchingFromGitHub ? "Fetching..." : "Fetch from GitHub"}
315→                </Button>
316→              </div>
317→            )}
318→          </div>
319→        </div>
320→      )}
321→
322→      {/* Empty state: App has access and session branch exists, but no checkpoints on this branch */}
323→      {showNoBranchCheckpoints && (
324→        <div className="border border-default rounded bg-raised p-8">
325→          <div className="text-center text-muted">
326→            <p className="text-lg font-medium">
327→              No checkpoints on this branch
328→            </p>
329→            <p className="mt-2 text-sm max-w-md mx-auto">
330→              This repository has Claude Code sessions, but none of them are
331→              linked to commits on the{" "}
332→              <code className="font-mono bg-muted px-1 rounded">
333→                {branch}
334→              </code>{" "}
335→              branch.
336→            </p>
337→            {isDev && (
338→              <div className="mt-4">
339→                <Button
340→                  variant="outline"
341→                  onClick={handleFetchFromGitHub}
