396→
397→function CheckpointsList(props: CheckpointsListProps) {
398→  const posthog = usePostHog();
399→  const {
400→    checkpoints,
401→    navigate,
402→    isDev,
403→    handleFetchFromGitHub,
404→    isFetchingFromGitHub,
405→    org,
406→    repo,
407→    branch,
408→    searchQuery,
409→    searchMeta,
410→  } = props;
411→
412→  const handleSelect = (index: number) => {
413→    const checkpoint = checkpoints[index];
414→    if (!checkpoint) return;
415→
416→    posthog.capture("checkpoint_clicked", {
417→      repository: `${org}/${repo}`,
418→      checkpoint_id: checkpoint.checkpointId,
419→    });
420→    navigate({
421→      to: "/gh/$org/$repo/checkpoints/$branch/$checkpointId",
422→      params: {
423→        org,
424→        repo,
425→        branch,
426→        checkpointId: checkpoint.checkpointId,
427→      },
428→    });
429→  };
430→
431→  return (
432→    <>
433→      <ListView
434→        itemCount={checkpoints.length}
435→        onSelect={handleSelect}
436→        aria-label="Checkpoints"
437→        className="@container border border-default rounded overflow-hidden bg-raised"
438→      >
439→        {checkpoints.map((checkpoint, index) => {
440→          // Aggregate session data
441→          const sessionCount = checkpoint.sessionCount;
442→          const uniqueAgents = checkpoint.agents;
443→
444→          const checkpointTitle = checkpoint.commitMessage;
445→
446→          const fileCount = checkpoint.fileStats?.length ?? 0;
447→
448→          const isSearch = searchQuery.length > 0;
449→          const meta = searchMeta?.[checkpoint.checkpointId];
450→
451→          // First session prompt (for search subtitle)
