453→          const truncatedPrompt = prompt
454→            ? prompt.length > 120 ? prompt.slice(0, 120) + "..." : prompt
455→            : null;
456→
457→          // Files matching search terms
458→          const matchedFiles = isSearch && checkpoint.filesTouched
459→            ? (() => {
460→                const words = searchQuery.trim().toLowerCase().split(/\s+/).filter(Boolean);
461→                return checkpoint.filesTouched
462→                  .filter((f) => words.some((w) => f.toLowerCase().includes(w)))
