465→            : [];
466→
467→          return (
468→            <ListViewItem
469→              key={checkpoint.checkpointId}
470→              index={index}
471→              href={`${GH_PATH_PREFIX}/${encodeURIComponent(org)}/${encodeURIComponent(repo)}/checkpoints/${encodeURIComponent(branch)}/${encodeURIComponent(checkpoint.checkpointId)}`}
472→              aria-label={`${checkpointTitle}, ${checkpoint.additions} additions, ${checkpoint.deletions} deletions, ${fileCount} ${fileCount === 1 ? "file" : "files"}, ${formatRelativeTime(checkpoint.commitDate)}, by ${checkpoint.commitAuthorUsername}`}
473→              className={`px-6 py-5 transition-colors hover:bg-hover ${
474→                index !== checkpoints.length - 1
475→                  ? "border-b border-default"
476→                  : ""
477→              }`}
478→            >
479→              <div className="flex flex-col @4xl:flex-row @4xl:items-center @4xl:justify-between gap-1 @4xl:gap-8">
480→                {/* Left: title + metadata */}
481→                <div className="min-w-0">
482→                  {isSearch ? (
483→                    <p className="font-semibold text-base text-default truncate">
484→                      <HighlightText text={checkpointTitle} query={searchQuery} />
485→                    </p>
486→                  ) : (
487→                    <p className="font-semibold text-base text-default truncate">
488→                      {checkpointTitle}
489→                    </p>
490→                  )}
491→                  {isSearch && truncatedPrompt && (
492→                    <p className="text-sm text-muted truncate mt-0.5">
493→                      <HighlightText text={truncatedPrompt} query={searchQuery} />
494→                    </p>
495→                  )}
496→                  <div className="flex flex-wrap items-center gap-x-1.5 gap-y-1 text-xs font-mono text-muted mt-1">
497→                    <Badge>
498→                      <code className="font-mono">
499→                        {checkpoint.checkpointId}
500→                      </code>
501→                    </Badge>
502→                    {isSearch && meta && (
503→                      <>
504→                        <span aria-hidden="true">·</span>
505→                        <MatchTypeBadge matchType={meta.matchType} />
506→                      </>
507→                    )}
508→                    <span aria-hidden="true">·</span>
509→                    <span className="flex flex-row items-center gap-1.5 shrink-0">
510→                      <Clock size={14} aria-hidden="true" />
511→                      {formatRelativeTime(checkpoint.commitDate)}
512→                    </span>
513→                    <span aria-hidden="true">·</span>
514→                    <span className="flex items-center gap-1 shrink-0">
515→                      <GitHubAvatar
516→                        username={checkpoint.commitAuthorUsername}
517→                        className="size-4"
518→                      />
519→                      <span>{checkpoint.commitAuthorUsername}</span>
520→                    </span>
521→                    {(uniqueAgents.length > 0 || sessionCount > 0) && (
522→                      <span aria-hidden="true">·</span>
523→                    )}
524→                    {uniqueAgents.length > 0 ? (
525→                      uniqueAgents.map((agent) => {
526→                        const config = getAgent(agent);
527→                        return (
528→                          <Badge
529→                            key={agent}
530→                            className={`${config.colorClass} agent-badge`}
531→                          >
532→                            {config.label}
533→                          </Badge>
534→                        );
535→                      })
536→                    ) : sessionCount > 0 ? (
537→                      <Badge className={`${getAgent(null).colorClass} agent-badge`}>
538→                        {getAgent(null).label}
539→                      </Badge>
540→                    ) : null}
541→                  </div>
542→                  {isSearch && matchedFiles.length > 0 && (
543→                    <div className="text-xs text-muted mt-1 font-mono truncate">
544→                      {matchedFiles.map((file, i) => (
