                  <span className="flex items-center gap-1.5">
                    <Clock size={13} aria-hidden="true" />
                    {formatRelativeTime(checkpoint.commitDate)}
                  </span>
                  <span aria-hidden="true" className="text-muted/50">|</span>
                  <span className="flex items-center gap-1.5">
